import React, { useState, useEffect, useCallback, useMemo } from "react";
import { Box, Typography, Chip, FormControl, Select, MenuItem } from "@mui/material";
import DataTable from "../../../components/DataTable";
import DetailsModal from "../../../components/DetailsModal";
import { useSelector } from "react-redux";
import { toast } from "react-hot-toast";
import dayjs from "dayjs";
import { apiGetJson } from "../../../utils/apiClient";

const LEVEL_COLORS = {
  INFO: "#4CC66E",
  WARN: "#F5A623",
  ERROR: "#FF5050",
  DEBUG: "#9F6EDA",
};

const SystemLogs = () => {
  const token = useSelector((state) => state.auth.token);

  const [logs, setLogs] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(25);
  const [searchTerm, setSearchTerm] = useState("");
  const [level, setLevel] = useState("ALL");

  const [selectedLog, setSelectedLog] = useState(null);
  const [openViewModal, setOpenViewModal] = useState(false);

  const fetchLogs = useCallback(
    async (apiPage, limit) => {
      if (!token) return;
      setIsLoading(true);
      try {
        const params = { page: apiPage, limit };
        if (searchTerm) params.search = searchTerm;
        if (level && level !== "ALL") params.level = level;

        const json = await apiGetJson("/logs", token, params);
        setLogs(Array.isArray(json.data) ? json.data : []);
        setTotalCount(json.pagination?.total || 0);
      } catch (err) {
        console.error("Error fetching logs:", err);
        toast.error(err.message || "Failed to load system logs");
      } finally {
        setIsLoading(false);
      }
    },
    [token, searchTerm, level]
  );

  useEffect(() => {
    if (token) fetchLogs(page + 1, rowsPerPage);
  }, [page, rowsPerPage, fetchLogs, token]);

  const handleViewDetails = (log) => {
    setSelectedLog(log);
    setOpenViewModal(true);
  };

  const columns = useMemo(
    () => [
      {
        id: "level",
        label: "Level",
        render: (row) => (
          <Chip
            label={row.level}
            size="small"
            sx={{
              bgcolor: `${LEVEL_COLORS[row.level] || "#8B8D97"}22`,
              color: LEVEL_COLORS[row.level] || "#8B8D97",
              fontWeight: 700,
              fontSize: "0.7rem",
              borderRadius: "6px",
            }}
          />
        ),
      },
      {
        id: "message",
        label: "Message",
        render: (row) => (
          <Box sx={{ maxWidth: 520 }}>
            <Typography
              sx={{
                color: "#FFFFFF",
                fontSize: "0.8rem",
                display: "-webkit-box",
                WebkitLineClamp: 2,
                WebkitBoxOrient: "vertical",
                overflow: "hidden",
              }}
            >
              {row.message || row.line || "-"}
            </Typography>
          </Box>
        ),
      },
      {
        id: "created_at",
        label: "Timestamp",
        render: (row) => (
          <Typography sx={{ color: "#8B8D97", fontSize: "0.8rem", whiteSpace: "nowrap" }}>
            {row.created_at ? dayjs(row.created_at).format("DD MMM YYYY, HH:mm:ss") : "-"}
          </Typography>
        ),
      },
    ],
    []
  );

  const detailsData = useMemo(() => {
    if (!selectedLog) return [];
    return [
      { label: "Level", value: selectedLog.level },
      { label: "Message", value: selectedLog.message || "-" },
      { label: "Line", value: selectedLog.line || "-" },
      {
        label: "Metadata",
        value:
          selectedLog.metadata && Object.keys(selectedLog.metadata).length
            ? JSON.stringify(selectedLog.metadata, null, 2)
            : "-",
      },
      {
        label: "Timestamp",
        value: selectedLog.created_at
          ? dayjs(selectedLog.created_at).format("DD MMM YYYY, HH:mm:ss")
          : "-",
      },
    ];
  }, [selectedLog]);

  const levelFilter = (
    <FormControl size="small" sx={{ minWidth: 130 }}>
      <Select
        value={level}
        onChange={(e) => {
          setLevel(e.target.value);
          setPage(0);
        }}
        sx={{
          height: 36,
          bgcolor: "rgba(255,255,255,0.05)",
          borderRadius: "8px",
          color: "rgba(255,255,255,0.85)",
          fontSize: "0.75rem",
          fontWeight: 600,
          fontFamily: "'Montserrat', sans-serif",
          "& .MuiOutlinedInput-notchedOutline": { borderColor: "rgba(255,255,255,0.12)" },
          "& .MuiSvgIcon-root": { color: "rgba(255,255,255,0.5)" },
        }}
        MenuProps={{
          PaperProps: {
            sx: {
              bgcolor: "#001e08ff",
              border: "1px solid rgba(255,255,255,0.1)",
              "& .MuiMenuItem-root": { fontSize: "0.78rem", color: "#fff" },
            },
          },
        }}
      >
        {["ALL", "INFO", "WARN", "ERROR", "DEBUG"].map((lvl) => (
          <MenuItem key={lvl} value={lvl}>
            {lvl === "ALL" ? "All Levels" : lvl}
          </MenuItem>
        ))}
      </Select>
    </FormControl>
  );

  return (
    <Box sx={{ p: { xs: 1, md: 3 } }}>
      <DataTable
        title="System Logs"
        columns={columns}
        data={logs}
        isLoading={isLoading}
        searchTerm={searchTerm}
        onSearchChange={(val) => {
          setSearchTerm(val);
          setPage(0);
        }}
        filters={levelFilter}
        onViewClick={handleViewDetails}
        orderBy="created_at"
        order="desc"
        pagination={{
          page,
          rowsPerPage,
          totalCount,
          onPageChange: (_, newPage) => setPage(newPage),
          onRowsPerPageChange: (e) => {
            setRowsPerPage(parseInt(e.target.value, 10));
            setPage(0);
          },
        }}
        emptyTitle="No logs found"
        emptyMessage="No log entries match your current filters."
      />

      {selectedLog && (
        <DetailsModal
          open={openViewModal}
          onClose={() => setOpenViewModal(false)}
          title="Log Details"
          data={detailsData}
          maxWidth="md"
        />
      )}
    </Box>
  );
};

export default SystemLogs;
